@OptIn(ExperimentalLayoutApi::class)
@Composable internal fun SearchScreen(repository: ArchiveRepository, connection: ServerConfiguration?, initialQuery: String, onConnect: () -> Unit, onOpen: (ArchiveSnapshot) -> Unit) {
    if (connection == null) { ConnectPrompt(onConnect); return }
    var query by rememberSaveable(initialQuery) { mutableStateOf(initialQuery) }
    var results by remember(connection) { mutableStateOf<List<ArchiveSnapshot>>(emptyList()) }
    var busy by remember { mutableStateOf(false) }
    var error by remember { mutableStateOf<String?>(null) }
    var searched by remember { mutableStateOf(false) }
    var more by remember { mutableStateOf(false) }
    var committedQuery by remember { mutableStateOf(initialQuery) }
    val scope = rememberCoroutineScope()
    val context = LocalContext.current
    suspend fun search(append: Boolean = false) {
        busy = true; error = null
        try {
            if (!append) committedQuery = query
            val page = repository.api.snapshots(connection, committedQuery, if (append) results.size else 0)
            results = if (append) (results + page).distinctBy { it.id } else page
            more = page.size == 50; searched = true
        } catch (e: Exception) { error = e.message ?: "Couldn't search your archive." }
        finally { busy = false }
    }
    LaunchedEffect(connection, initialQuery) { search() }
    LazyColumn(Modifier.fillMaxSize().testTag("search"), contentPadding = PaddingValues(20.dp), verticalArrangement = Arrangement.spacedBy(14.dp)) {
        item {
            OutlinedTextField(query, { query = it }, label = { Text("Search titles, URLs, and tags") }, leadingIcon = { Icon(Icons.Outlined.Search, null) }, trailingIcon = { IconButton(onClick = { scope.launch { search() } }, enabled = !busy, modifier = Modifier.testTag("search.submit")) { Icon(Icons.Outlined.ArrowForward, "Search") } }, singleLine = true, keyboardOptions = KeyboardOptions(imeAction = ImeAction.Search), keyboardActions = KeyboardActions(onSearch = { scope.launch { search() } }), modifier = Modifier.fillMaxWidth().testTag("search.query"))
        }
        if (busy) item { LinearProgressIndicator(Modifier.fillMaxWidth()) }
        error?.let { message -> item { ErrorCard(message); TextButton(onClick = { scope.launch { search() } }) { Text("Try again") } } }
        if (searched && results.isEmpty() && !busy && error == null) item {
            Column(Modifier.padding(vertical = 48.dp), verticalArrangement = Arrangement.spacedBy(12.dp)) { Icon(Icons.Outlined.SearchOff, null, Modifier.size(48.dp), tint = MaterialTheme.colorScheme.primary); Text("No saved pages found", style = MaterialTheme.typography.headlineSmall); Text("Try another title, URL, or tag, or save your first link from the Add tab.", color = MaterialTheme.colorScheme.onSurfaceVariant) }
        }
        if (results.isNotEmpty()) item { Text(if (committedQuery.isBlank()) "Your latest saved pages" else "Results for “$committedQuery”", style = MaterialTheme.typography.titleSmall, modifier = Modifier.testTag("search.results")) }
        items(results, key = { it.id }) { snapshot ->
            Card(onClick = { onOpen(snapshot) }, shape = RoundedCornerShape(22.dp), colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surfaceContainerLow), modifier = Modifier.fillMaxWidth().testTag("search.result.${snapshot.id}")) {
                Column(Modifier.padding(18.dp), verticalArrangement = Arrangement.spacedBy(10.dp)) {
                    Row(horizontalArrangement = Arrangement.spacedBy(12.dp)) { Icon(Icons.Outlined.Language, null, tint = MaterialTheme.colorScheme.primary); Text(snapshot.title.ifBlank { snapshot.url }, style = MaterialTheme.typography.titleMedium, maxLines = 3, overflow = TextOverflow.Ellipsis, modifier = Modifier.weight(1f)) }
                    Text(snapshot.url, maxLines = 2, overflow = TextOverflow.Ellipsis, style = MaterialTheme.typography.bodySmall, color = MaterialTheme.colorScheme.onSurfaceVariant)
                    FlowRow(horizontalArrangement = Arrangement.spacedBy(6.dp)) { snapshot.tags.forEach { tag -> SuggestionChip(onClick = { query = tag; scope.launch { search() } }, label = { Text(tag) }, icon = { Icon(Icons.Outlined.Sell, null, Modifier.size(14.dp)) }) } }
                    Row(horizontalArrangement = Arrangement.spacedBy(8.dp)) {
                        TextButton(onClick = { onOpen(snapshot) }) { Text("Open saved page"); Spacer(Modifier.width(6.dp)); Icon(Icons.Outlined.ArrowOutward, null, Modifier.size(16.dp)) }
                        IconButton(onClick = {
                            val intent = Intent(Intent.ACTION_SEND).setType("text/plain").putExtra(Intent.EXTRA_TEXT, snapshot.url).putExtra(Intent.EXTRA_TITLE, snapshot.title)
                            context.startActivity(Intent.createChooser(intent, "Share original URL"))
                        }) { Icon(Icons.Outlined.Share, "Share original URL") }
                        IconButton(onClick = {
                            val link = "${connection.server.trimEnd('/')}/snapshot/${snapshot.id}/index.html"
                            context.startActivity(Intent.createChooser(Intent(Intent.ACTION_SEND).setType("text/plain").putExtra(Intent.EXTRA_TEXT, link), "Share archived page"))
                        }) { Icon(Icons.Outlined.Link, "Share archived page") }
                    }
                }
            }
        }
        if (more) item { OutlinedButton(onClick = { scope.launch { search(true) } }, enabled = !busy, modifier = Modifier.fillMaxWidth().testTag("search.more")) { Text("Load more") } }
    }
}

#!/usr/bin/env node
// Exercise actual git history, including reruns and patch rollover.
import {execFileSync} from 'node:child_process';
import {mkdtempSync, mkdirSync, writeFileSync, rmSync} from 'node:fs';
import {tmpdir} from 'node:os';
import {join, resolve} from 'node:path';
import assert from 'node:assert/strict';
const script = resolve('scripts/release-version.mjs');
const directory = mkdtempSync(join(tmpdir(), 'archivebox-version-'));
const git = (...args) => execFileSync('git', args, {cwd: directory, stdio: 'pipe'});
const run = (event = 'push') => Object.fromEntries(execFileSync(process.execPath, [script], {
  cwd: directory, encoding: 'utf8', env: {...process.env, GITHUB_EVENT_NAME: event, GITHUB_OUTPUT: ''},
}).trim().split('\n').map(line => line.split('=')));
try {
  git('init', '-b', 'main');
  git('config', 'user.name', 'ArchiveBox version test');
  git('config', 'user.email', 'version-test@example.invalid');
  writeFileSync(join(directory, 'version.properties'), 'versionName=0.1.0\nversionCode=1000\n');
  git('add', '.'); git('commit', '-m', 'Initial version');
  assert.equal(run().version, '0.1.0'); assert.equal(run().code, '1000');
  git('tag', 'v0.1.0');
  assert.equal(run().version, '0.1.0', 'Rerunning the tagged commit must not bump');
  writeFileSync(join(directory, 'README.md'), 'Marketing copy\n');
  git('add', '.'); git('commit', '-m', 'Update marketing copy');
  assert.equal(run('workflow_dispatch').version, '0.1.0', 'Server capture reuses the release after marketing-only commits');
  assert.equal(run('schedule').version, '0.1.0', 'Scheduled gallery reuses the published version after marketing-only commits');
  mkdirSync(join(directory, 'app/src/androidTest'), {recursive: true});
  writeFileSync(join(directory, 'app/src/androidTest/JourneyTest.kt'), 'Updated capture journey\n');
  mkdirSync(join(directory, 'app/src/test'), {recursive: true});
  writeFileSync(join(directory, 'app/src/test/ReleaseTest.kt'), 'Updated release test\n');
  mkdirSync(join(directory, '.github/workflows'), {recursive: true});
  writeFileSync(join(directory, '.github/workflows/ci.yml'), 'Updated CI\n');
  mkdirSync(join(directory, 'scripts'), {recursive: true});
  writeFileSync(join(directory, 'scripts/export-capture-diagnostics.py'), 'Public capture diagnostics only\n');
  git('add', '.'); git('commit', '-m', 'Update capture journey and CI');
  assert.equal(run('workflow_dispatch').version, '0.1.0', 'Server capture reuses the release after capture-only changes');
  mkdirSync(join(directory, 'app'), {recursive: true});
  writeFileSync(join(directory, 'app/proguard-rules.pro'), '-keep class example.** { *; }\n');
  git('add', '.'); git('commit', '-m', 'Change Android release packaging');
  assert.throws(() => run('workflow_dispatch'), /Unreleased Android app changes/);
  assert.throws(() => run('schedule'), /Unreleased Android app changes/);
  git('commit', '--allow-empty', '-m', 'App change');
  assert.equal(run().version, '0.1.1'); assert.equal(run().code, '1001');
  writeFileSync(join(directory, 'version.properties'), 'versionName=0.1.0\nversionCode=1000\n# runtime change\n');
  git('add', '.'); git('commit', '-m', 'Change runtime input');
  assert.throws(() => run('workflow_dispatch'), /Unreleased Android app changes/);
  assert.throws(() => run('schedule'), /Unreleased Android app changes/);
  git('tag', 'v0.1.999');
  git('commit', '--allow-empty', '-m', 'Next app change');
  assert.equal(run().version, '0.2.0'); assert.equal(run().code, '2000');
  writeFileSync(join(directory, 'version.properties'), 'versionName=1.0.0\nversionCode=1000000\n');
  assert.equal(run().version, '1.0.0'); assert.equal(run().code, '1000000');
  console.log('Release versions verified with real git tags and commits.');
} finally {
  rmSync(directory, {recursive: true, force: true});
}

package io.archivebox.app

import android.graphics.Bitmap
import androidx.test.ext.junit.runners.AndroidJUnit4
import androidx.test.platform.app.InstrumentationRegistry
import androidx.test.uiautomator.By
import androidx.test.uiautomator.Until
import androidx.test.uiautomator.UiDevice
import org.junit.Assert.assertTrue
import org.junit.Test
import org.junit.runner.RunWith
import java.io.File

/** Launcher interaction has its own lifecycle, outside a Compose ActivityScenario. */
@RunWith(AndroidJUnit4::class)
class WidgetJourneyTest {
    @Test fun installWidgetAndOpenItsActions() {
        val instrumentation = InstrumentationRegistry.getInstrumentation()
        val device = UiDevice.getInstance(instrumentation)
        val output = File(instrumentation.targetContext.getExternalFilesDir(null), "screenshots").apply { mkdirs() }
        device.pressHome()
        device.waitForIdle()
        val widgetSearch = By.res("io.archivebox.app", "widget_search")
        if (!device.hasObject(widgetSearch)) {
            // Long-press the actual launcher workspace to open its widget menu.
            requireNotNull(device.findObject(By.res("com.google.android.apps.nexuslauncher", "workspace"))) {
                "Launcher workspace missing"
            }.longClick()
            val widgets = device.wait(Until.findObject(By.textContains("Widgets")), 5_000)
            if (widgets == null) {
                val menu = requireNotNull(instrumentation.uiAutomation.takeScreenshot())
                File(output, "widget-menu-failure.png").outputStream().use { assertTrue(menu.compress(Bitmap.CompressFormat.PNG, 100, it)) }
                menu.recycle()
                device.dumpWindowHierarchy(File(output, "widget-menu-failure.xml"))
                throw AssertionError("Launcher Widgets action missing")
            }
            widgets.click()
            requireNotNull(device.wait(Until.findObject(By.desc("Browse widgets")), 5_000)) { "Widget Browse tab missing" }.click()
            val archiveBox = device.wait(Until.findObject(By.textContains("ArchiveBox")), 5_000)
            if (archiveBox == null) {
                val picker = requireNotNull(instrumentation.uiAutomation.takeScreenshot())
                File(output, "widget-picker-failure.png").outputStream().use { assertTrue(picker.compress(Bitmap.CompressFormat.PNG, 100, it)) }
                picker.recycle()
                device.dumpWindowHierarchy(File(output, "widget-picker-failure.xml"))
                throw AssertionError("ArchiveBox missing from actual widget picker")
            }
            archiveBox.click()
            requireNotNull(device.wait(Until.findObject(By.res("com.android.launcher3.widgetpicker", "widget_preview")), 5_000)) { "Widget preview missing" }.click()
            requireNotNull(device.wait(Until.findObject(By.desc("Add ArchiveBox widget")), 5_000)) { "Widget Add action missing" }.click()
        }
        requireNotNull(device.wait(Until.findObject(widgetSearch), 5_000)) { "Widget was not installed on the launcher" }
        device.waitForIdle()
        val bitmap = requireNotNull(instrumentation.uiAutomation.takeScreenshot())
        File(output, "widget.png").outputStream().use { assertTrue(bitmap.compress(Bitmap.CompressFormat.PNG, 100, it)) }
        bitmap.recycle()
        device.findObject(widgetSearch).click()
        assertTrue("Widget Search action must open native Search Archive", device.wait(Until.hasObject(By.text("Search Archive")), 5_000))
        device.pressHome()
        requireNotNull(device.wait(Until.findObject(By.res("io.archivebox.app", "widget_add")), 5_000)).click()
        assertTrue("Widget Save action must open the real save sheet", device.wait(Until.hasObject(By.text("Save to ArchiveBox")), 5_000))
    }
}

package io.archivebox.app

import android.content.Intent
import android.content.res.Configuration
import android.graphics.Bitmap
import android.graphics.Color
import androidx.compose.ui.test.*
import androidx.compose.ui.test.junit4.v2.createEmptyComposeRule
import androidx.test.ext.junit.runners.AndroidJUnit4
import androidx.test.platform.app.InstrumentationRegistry
import androidx.test.uiautomator.UiDevice
import org.junit.Assert.assertTrue
import org.junit.Rule
import org.junit.Test
import org.junit.runner.RunWith
import java.io.File

/** Real system configuration changes, restored even when an assertion fails. */
@RunWith(AndroidJUnit4::class)
class VisualProfilesTest {
    @get:Rule val compose = createEmptyComposeRule()
    private val instrumentation get() = InstrumentationRegistry.getInstrumentation()
    private val device get() = UiDevice.getInstance(instrumentation)
    private val context get() = instrumentation.targetContext
    private fun shell(command: String) = device.executeShellCommand(command)
    private fun awaitHome() {
        compose.waitUntil(10_000) { compose.onAllNodesWithTag("tab.Archive").fetchSemanticsNodes().isNotEmpty() }
        if (compose.onAllNodesWithTag("share.sheet").fetchSemanticsNodes().isNotEmpty()) device.pressBack()
        compose.onNodeWithTag("tab.Archive").performClick()
        compose.onNodeWithTag("home").assertIsDisplayed()
    }
    private fun capture(id: String, dark: Boolean = false) {
        compose.waitForIdle()
        device.waitForIdle()
        val bitmap = requireNotNull(instrumentation.uiAutomation.takeScreenshot())
        try {
            if (dark) assertTrue("The rendered app background must actually be dark", Color.luminance(bitmap.getPixel(bitmap.width - 8, bitmap.height / 2)) < 0.2f)
            val output = File(context.getExternalFilesDir(null), "screenshots").apply { mkdirs() }
            File(output, "$id.png").outputStream().use { assertTrue(bitmap.compress(Bitmap.CompressFormat.PNG, 100, it)) }
        } finally { bitmap.recycle() }
    }

    @Test fun darkThemeAndTabletNavigation() {
        val size = Regex("Override size: ([0-9]+x[0-9]+)").find(shell("wm size"))?.groupValues?.get(1)
        val density = Regex("Override density: ([0-9]+)").find(shell("wm density"))?.groupValues?.get(1)
        val night = requireNotNull(Regex("Night mode: (auto|yes|no)\\b").find(shell("cmd uimode night"))) { "The dedicated test device must use auto, yes, or no night mode" }.groupValues[1]
        context.startActivity(requireNotNull(context.packageManager.getLaunchIntentForPackage("io.archivebox.app")).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK))
        try {
            awaitHome()
            shell("cmd uimode night yes")
            compose.waitUntil(10_000) { context.resources.configuration.uiMode and Configuration.UI_MODE_NIGHT_MASK == Configuration.UI_MODE_NIGHT_YES }
            awaitHome()
            capture("dark-mode", dark = true)

            shell("cmd uimode night no")
            shell("wm size 1280x800")
            shell("wm density 160")
            compose.waitUntil(10_000) { context.resources.configuration.screenWidthDp >= 700 }
            awaitHome()
            compose.onNodeWithTag("navigation.rail").assertIsDisplayed()
            compose.onNodeWithTag("tab.Search").assertIsDisplayed()
            capture("tablet")
        } finally {
            shell("wm density ${density ?: "reset"}")
            shell("wm size ${size ?: "reset"}")
            shell("cmd uimode night $night")
        }
    }
}
